  "answer": {
    "kind": "student",
    "resposta": "",
    "raciocinio": "O problema original tem três falhas: o fetch não tem timeout, então a requisição
fica pendente por tempo indeterminado; o status HTTP não é verificado, então
respostas de erro são processadas como sucesso; e não há retry para erros
transitórios.

Corrigi usando AbortController com timer de 3 segundos. Se o AbortError for
disparado, capturo e converto em mensagem descritiva. Para respostas com status
não-ok, armazeno o erro e retento na próxima iteração. O loop garante no máximo
2 tentativas.

O GET é idempotente, então retry é seguro aqui. O trade-off é a latência
adicional: no pior caso, 6 segundos de espera antes de falhar.
",
    "codigo": "// exchange-rate.js

const API_BASE_URL = 'https://api.exchangerates.example.com';
const TIMEOUT_MS  = 3000;
const MAX_RETRIES = 1;

async function getExchangeRate(fromCurrency, toCurrency) {
  const url = `${API_BASE_URL}/latest?base=${fromCurrency}&symbols=${toCurrency}`;
  let lastError;

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

      let response;
      try {
        response = await fetch(url, { signal: controller.signal });
      } finally {
        clearTimeout(timer);
      }

      if (!response.ok) {
        // Trata qualquer erro HTTP como transitório e retenta
        lastError = new Error(`HTTP error: ${response.status}`);
        continue;
      }

      const data = await response.json();
      return data.rates[toCurrency];

    } catch (err) {
      lastError = err.name === 'AbortError'
        ? new Error(`Request timed out after ${TIMEOUT_MS}ms`)
        : err;
    }
  }

  throw lastError ?? new Error('Failed to fetch exchange rate');
}

module.exports = { getExchangeRate, TIMEOUT_MS, MAX_RETRIES };
